const e=[{unit:1,id:"countmatch",iso:"2026-08-17",date:"Mon 17 Aug 2026",source:"Build and Count",preferred:5,focus:"one-to-one counting",name:"Picture Match",summary:"Count a pictured set—animals, fruit, shells, or stars—and show exactly the same amount.",grows:"This grows out of seeing sets of 1–5 linking cubes and making a set with the same amount.",steps:["Touch or point to each picture once.","Build or show the same amount.","Reveal the numeral and recount together."],materials:"Cubes, fingers, number cards, or a device.",brainGame:"Apple Count Orchard"},{unit:1,id:"exactsame",iso:"2026-08-19",date:"Wed 19 Aug 2026",source:"Exactly the Same",preferred:5,focus:"attributes and orientation",name:"Exactly the Same?",summary:"Decide whether two picture cards are exactly the same—even when one has turned.",grows:"This grows out of comparing two cubes by color, shape, size, and orientation, then naming exactly the same or not exactly the same.",steps:["Look closely at both cards.","Signal exactly the same or not exactly.","Reveal and name what changed—or what only turned."],materials:"Same/not-same cards, pointing, speech, or a device.",brainGame:"Sorting Museum"},{unit:1,id:"alike",iso:"2026-08-21",date:"Fri 21 Aug 2026",source:"Alike in One Way",preferred:5,focus:"describe a shared attribute",name:"Find One Way Alike",summary:"Study two picture cards and find one true way they are alike.",grows:"This grows out of comparing a linking cube with a drawn square, then comparing towers with different heights.",steps:["Look at both cards.","Point, say, or select one way they are alike.","Reveal one possible answer and discuss another."],materials:"Attribute words, pointing, speech, or a device.",brainGame:"Sorting Museum"},{unit:1,id:"secretrule",iso:"2026-08-25",date:"Tue 25 Aug 2026",source:"Choose a Sorting Rule",preferred:5,focus:"infer and test a rule",name:"Secret Sorting Rule",summary:"Study the example cards and decide whether the mystery card follows their rule.",grows:"This grows out of sorting six cubes by a secret color rule, inferring it, and testing a new cube.",steps:["Notice what all example cards share.","Signal yes or no for the mystery card.","Reveal the rule and test the card together."],materials:"Yes/no cards, attribute words, pointing, or a device.",brainGame:"Sorting Museum"},{unit:1,id:"inout",iso:"2026-08-27",date:"Thu 27 Aug 2026",source:"Two Categories",preferred:5,focus:"sort in or out",name:"In or Out?",summary:"Read the picture rule and decide whether the mystery object belongs inside.",grows:"This grows out of sorting single cubes and towers into connected and not connected categories.",steps:["Look at the category rule.","Signal in or out for the mystery object.","Reveal and explain which attribute decides."],materials:"In/out cards, pointing, speech, or a device.",brainGame:"Sorting Museum"},{unit:1,id:"threehomes",iso:"2026-08-31",date:"Mon 31 Aug 2026",source:"Three Categories",preferred:3,focus:"match group to numeral",name:"Three Counting Homes",summary:"Count a group of acorns and choose the numbered home where it belongs.",grows:"This grows out of placing groups of one, two, or three cubes into three labeled category circles, regardless of color.",steps:["Count each acorn once.","Choose the home with the matching numeral.","Reveal and check the match together."],materials:"Number cards, fingers, pointing, or a device.",brainGame:"Apple Count Orchard"},{unit:1,id:"rowsame",iso:"2026-09-02",date:"Wed 2 Sep 2026",source:"Rows and Columns",preferred:5,focus:"arrangement keeps quantity",name:"Row or Column",summary:"Compare stars in a row and a column and decide whether the amount stayed the same.",grows:"This grows out of a quick look at cubes in a row, then the same cubes in a column, before building the same amount.",steps:["Count or recognize each group.","Signal same amount or not the same.","Reveal both counts and explain what moved."],materials:"Same/not-same cards, fingers, pointing, or a device.",brainGame:"Apple Count Orchard"},{unit:1,id:"storychange",themeOffset:0,iso:"2026-09-04",date:"Fri 4 Sep 2026",source:"Unit Math Check",preferred:5,focus:"join and separate",name:"Story Scene Changes",summary:"Join pictured groups or watch animals and objects move away, then find the new amount.",grows:"This grows out of Build It, Push It, Slash It: build 3 and join 2, then build 5 and move 1 away.",steps:["Count the starting group or two parts.","Act out the join or move-away change.","Show the new amount; then reveal."],materials:"Cubes, fingers, number cards, or a device.",brainGame:"Story Stage"},{unit:1,id:"storychange",themeOffset:2,iso:"2026-09-08",date:"Tue 8 Sep 2026",source:"Unit 1 Close",preferred:5,focus:"join and separate",name:"Story Scene Finale",summary:"Replay the unit check with animals, fruit, flowers, shells, and butterflies.",grows:"This grows out of the Unit 1 closing rounds of Build It, Push It, Slash It.",steps:["Count the starting group or two parts.","Act out the join or move-away change.","Show the new amount; then reveal."],materials:"Cubes, fingers, number cards, or a device.",brainGame:"Story Stage"},{unit:2,id:"fieldwater",iso:"2026-09-10",date:"Thu 10 Sep 2026",source:"Lessons 11–12",preferred:5,focus:"parts keep the whole",name:"Field, Water, One Whole",summary:"Count bears in the field and water, then show the whole that stays the same.",grows:"This grows out of sliding bears between the field and water, pushing the parts together, and recounting the same whole.",steps:["Count the bears in each place.","Build or show both visible parts.","Show how many altogether; then reveal the whole."],materials:"Cubes, fingers, number cards, or a device.",brainGame:"Penguin Iceberg Rescue"},{unit:2,id:"empty",iso:"2026-09-14",date:"Mon 14 Sep 2026",source:"Lessons 13–14",preferred:3,focus:"zero means none",name:"Empty Hand, Number Card",summary:"Count what remains—even when none remain—then reveal the numeral.",grows:"This grows out of taking cubes from a tower one at a time until the hand is empty, then writing the numeral for how many remain.",steps:["Look at how many cubes remain.","Show the number with fingers, a card, or a device.","Reveal the numeral and check together."],materials:"Cubes, fingers, number cards, or a device.",brainGame:"Apple Count Orchard"},{unit:2,id:"parts",iso:"2026-09-16",date:"Wed 16 Sep 2026",source:"Lessons 15–16",preferred:5,focus:"parts make a whole",name:"Parts Stay Whole",summary:"Join two visible parts and work out the hidden whole.",grows:"This grows out of breaking a stick of cubes into two parts and putting it back together.",steps:["Look at the two visible parts.","Build or show both parts.","Show how many altogether; then reveal the whole."],materials:"Cubes, fingers, number cards, or a device.",brainGame:"Penguin Iceberg Rescue"},{unit:2,id:"order",iso:"2026-09-18",date:"Fri 18 Sep 2026",source:"Lessons 17–18",preferred:10,focus:"order and quantity",name:"Order & Shape",summary:"Find the missing number, then see the same amount in a new shape.",grows:"This grows out of putting shuffled number cards back in order and arranging the same set in lines and boxes.",steps:["Follow the number-card order.","Show the missing number.","Reveal, then notice that a new shape keeps the count."],materials:"Number cards, cubes, fingers, or a device.",brainGame:"Apple Count Orchard"},{unit:2,id:"necklace",iso:"2026-09-22",date:"Tue 22 Sep 2026",source:"Lessons 19–20",preferred:10,focus:"count a ring once",name:"Necklace Count",summary:"Count a ring from its marked start without counting any piece twice.",grows:"This grows out of counting scattered beans, sliding them into a magic necklace, and counting the same set again.",steps:["Find the marked starting piece.","Point around the ring and stop before the mark.","Show how many; then reveal."],materials:"Counters, fingers, number cards, or a device.",brainGame:"Apple Count Orchard"},{unit:2,id:"move",iso:"2026-09-24",date:"Thu 24 Sep 2026",source:"Lessons 21–22",preferred:10,focus:"same, more, or fewer",name:"Move It, Keep the Count",summary:"Compare two arrangements after the counters move.",grows:"This grows out of moving one set through a tower, rows, columns, and the four edges while its count stays the same.",steps:["Look at both arrangements.","Show same, more, or fewer.","Reveal and check by counting."],materials:"Counters, comparison cards, fingers, or a device.",brainGame:"Apple Count Orchard"},{unit:2,id:"ringrows",iso:"2026-09-28",date:"Mon 28 Sep 2026",source:"Lessons 23–24",preferred:10,focus:"arrange and count",name:"Ring to Rows",summary:"Count an arranged set and reveal the numeral that names it.",grows:"This grows out of making a ring around a marked cup, then building nine as three rows of three.",steps:["Find a sensible place to start.","Point once to each counter.","Show the numeral; then reveal."],materials:"Counters, number cards, fingers, or a device.",brainGame:"Apple Count Orchard"},{unit:2,id:"ten",iso:"2026-09-30",date:"Wed 30 Sep 2026",source:"Lessons 25–26",preferred:10,focus:"ten as two fives",name:"See Ten Quickly",summary:"Use five-groups to see a total without losing your place.",grows:"This grows out of filling a five-group mat with two fives, then turning ten into five rows of two.",steps:["Look for full groups of five.","Show the total with a card, fingers, or a device.","Reveal and explain what made it easy to see."],materials:"A five-group mat, counters, number cards, or a device.",brainGame:"Quick Look Lighthouse"},{unit:2,id:"party",iso:"2026-10-02",date:"Fri 2 Oct 2026",source:"Lessons 27–29",preferred:10,focus:"a quantity changes",name:"The Party Changes",summary:"Watch a group change when some party guests leave.",grows:"This grows out of moving the same ten counters into new arrangements, then acting out a story as children leave a party.",steps:["Count how many are at the party.","Notice how many leave.","Show how many remain; then reveal."],materials:"Counters, fingers, number cards, or a device.",brainGame:"Story Stage"},{unit:2,id:"wallcount",iso:"2026-10-06",date:"Tue 6 Oct 2026",source:"Teacher-created",preferred:10,focus:"compare and check",name:"Count the Exhibition",summary:"Count the artworks on two parts of our exhibition wall, compare them, and check a count the teacher gives.",grows:"This grows out of Count the Exhibition, where the room guessed, then counted the artworks on our wall together, touching each one, wrote both numbers, said which side has more and how we know, and checked a count the teacher gave.",steps:["Count the artworks on each part of the wall, one touch for each.","Show same, more or fewer — or keep or change the number on the label.","Tap Reveal to count both parts and compare."],materials:"Counters, comparison cards, fingers, number cards 0 to 10, or a device",brainGame:"Croc Snack Cannon"},{unit:3,id:"one-more-stair",iso:"2026-10-13",date:"Tue 13 Oct 2026",source:"Bluebonnet Kindergarten Math Module 1, Lessons 30–31",preferred:10,focus:"one more is the next number",name:"One More Stair",summary:"Watch the stairs grow and show how many are on the next step.",grows:"This grows out of Baby Bear’s stairs, where the room built cube stairs that go up by one and said “3. One more is 4” at every step.",steps:["Look at the step on the board and count it.","Show the next step — one more — with cubes, fingers or a number card.","Tap Reveal and say it together: “4. One more is 5.”"],materials:"Linking cubes, fingers, number cards 1 to 10, or a device",brainGame:"Labyrinth Stairs"},{unit:3,id:"which-towers-are-hiding",iso:"2026-10-15",date:"Thu 15 Oct 2026",source:"Bluebonnet Kindergarten Math Module 1, Lessons 32–33",preferred:10,focus:"one more, one less",name:"Which Towers Are Hiding?",summary:"Some towers in the stairs are hiding — show which numbers are missing.",grows:"This grows out of the hidden towers, where the room closed its eyes while towers were taken out of the 1-to-10 stairs and worked out which were gone, then took cubes off a ten one at a time.",steps:["Look at the stairs and find the gap.","Show the missing number with a tower, fingers, a number card or by pointing.","Tap Reveal, then say the numbers one more and one less than it."],materials:"Linking cube towers 1 to 10, number cards 1 to 10, fingers, or a device",brainGame:"Labyrinth Stairs"},{unit:3,id:"down-the-stairs",iso:"2026-10-19",date:"Mon 19 Oct 2026",source:"Bluebonnet Kindergarten Math Module 1, Lessons 34–35",preferred:10,focus:"one less is the step below",name:"Down the Stairs",summary:"See the step and show the one below it — one less.",grows:"This grows out of Baby Bear going down the stairs, where the room took one cube at a time off a stair of ten and said “10. One less is 9” at every step.",steps:["Look at the stair on the board and count it.","Show the stair below it — one less — with cubes, fingers or a number card.","Tap Reveal and say it together: “6. One less is 5.”"],materials:"Linking cube stairs, fingers, number cards 0 to 10, or a device",brainGame:"Labyrinth Stairs"},{unit:3,id:"before-and-after",iso:"2026-10-21",date:"Wed 21 Oct 2026",source:"Teacher-created review of Bluebonnet Kindergarten Math Module 1, Topics E–H",preferred:10,focus:"the number before and the number after",name:"Before and After",summary:"Look at the tower and show the number just before it or just after it.",grows:"This grows out of the one more, one less echo, where the room held up a card and said “I have 5. One more is 6” and “5. One less is 4.”",steps:["Look at the tower and the arrow — up means one more, down means one less.","Show the number just after or just before it with cubes, fingers or a number card.","Tap Reveal and say it together: “7. One more is 8.”"],materials:"Linking cubes, number cards 0 to 10, fingers, or a device",brainGame:"Labyrinth Stairs"},{unit:3,id:"triangle-hunt",iso:"2026-10-23",date:"Fri 23 Oct 2026",source:"Bluebonnet Kindergarten Math Module 2, Lessons 1–2",preferred:5,focus:"three straight sides, three corners, closed",name:"Triangle Hunt",summary:"Find every triangle in the picture and show how many.",grows:"This grows out of the Triangle and Not a Triangle graph, where the room counted straight sides and corners and checked each shape was closed before it went in a column.",steps:["Look at every shape in the picture and find the triangles.","Show how many triangles with fingers, a number card or by pointing.","Tap Reveal, watch each triangle light up, and count them together."],materials:"Fingers, number cards 0 to 10, a whiteboard to draw a triangle, or a device",brainGame:"Shape Invasion Defence"},{unit:3,id:"rectangle-and-circle-hunt",iso:"2026-10-27",date:"Tue 27 Oct 2026",source:"Bluebonnet Kindergarten Math Module 2, Lessons 3–4",preferred:5,focus:"square corners, or no corners at all",name:"Rectangle and Circle Hunt",summary:"Find the rectangles, or the circles, and show how many.",grows:"This grows out of the Rectangle and Circle picture graphs, where the room sorted shapes by four straight sides and square corners, then by round, closed and no corners.",steps:["Look at the small shape at the top: today we hunt rectangles, or circles.","Show how many are in the picture with fingers, a number card or by pointing.","Tap Reveal, watch each one light up, and count them together."],materials:"Fingers, number cards 0 to 10, a whiteboard to draw the shape, or a device",brainGame:"Shape Invasion Defence"},{unit:3,id:"how-many-faces",iso:"2026-10-29",date:"Thu 29 Oct 2026",source:"Bluebonnet Kindergarten Math Module 2, Lessons 5–6",preferred:10,focus:"a face is a flat part you can trace",name:"How Many Faces?",summary:"Look at the solid and show how many flat faces it has.",grows:"This grows out of Face or No Face, where the room touched and counted the flat faces of a cone, a cylinder and a cube, and found that a sphere has none.",steps:["Look at the solid on the board and find its flat faces.","Show how many faces with fingers, a number card, or by holding up the same solid.","Tap Reveal, watch each face light up, and count them together."],materials:"A ball, a cube, a capped marker, a Play-Doh cone, fingers, number cards 0 to 10, or a device",brainGame:"Shape Invasion Defence"},{unit:3,id:"flat-or-solid",iso:"2026-11-02",date:"Mon 2 Nov 2026",source:"Bluebonnet Kindergarten Math Module 2, Lessons 7–8",preferred:5,focus:"flat lies down, solid stands up",name:"Flat or Solid?",summary:"Look at the table and show how many things are solid.",grows:"This grows out of Bird and Ant, where the room looked across the desks and saw that the solids stood up while the flat card and the drawings disappeared, then sorted flat from solid.",steps:["Look at everything on the table, whichever way it is turned.","Show how many are solid with fingers, a number card, or by holding up the matching solid.","Tap Reveal, watch each solid stand up, and count them together."],materials:"A ball, a cube, a capped marker, a Play-Doh cone, a flat card, fingers, number cards 0 to 10, or a device",brainGame:"Shape Invasion Defence"},{unit:3,id:"still-the-same-shape",iso:"2026-11-04",date:"Wed 4 Nov 2026",source:"Teacher-created review of Bluebonnet Kindergarten Math Module 2, Topics A–C",preferred:5,focus:"turn it or flip it, it is still the same shape",name:"Still the Same Shape",summary:"Find every shape that matches the one at the top, however it is turned.",grows:"This grows out of the Triangle, Rectangle and Circle graph and Guess My Rule, where triangles pointing down, squares turned sideways and cones upside down kept their names.",steps:["Look at the shape at the top.","Show how many shapes below are the same shape, however they are turned.","Tap Reveal, watch each one turn back to match, and count them together."],materials:"A ball, a cube, a capped marker, a Play-Doh cone, fingers, number cards 0 to 10, or a device",brainGame:"Shape Invasion Defence"},{unit:3,id:"picture-graph-count",iso:"2026-11-06",date:"Fri 6 Nov 2026",source:"Teacher-created: our four weeks of observations",preferred:5,focus:"count each column, then compare",name:"Picture Graph Count",summary:"Count the column the arrow shows — then find the column with more.",grows:"This grows out of our journal graph and our Did It Change? towers, where the room coloured one box for each page and each observation, then compared the columns.",steps:["Look at the column the arrow points to.","Show how many boxes are in it with fingers, a number card or cubes.","Tap Reveal, count the boxes together, and point to the column with more."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Picture Graph Parade"},{unit:4,id:"line-up-the-ends",iso:"2026-11-10",date:"Tue 10 Nov 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 1–2",preferred:5,focus:"line up the ends",name:"Line Up the Ends",summary:"Line up the ends, then show which stick is longer.",grows:"This grows out of the Magic Show and Longer Than My Strip, where the room lined up cube sticks and paper strips at the edge of a desk before deciding which was longer.",steps:["Look at the two sticks, even if their ends do not line up.","Point to the one you think is really longer, and show how many cubes longer with fingers or cubes.","Tap Reveal, watch the ends slide into line, and count the difference together."],materials:"Two linking-cube sticks, a strip of paper, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:4,id:"longer-than-five",iso:"2026-11-12",date:"Thu 12 Nov 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 3–4",preferred:10,focus:"five is the stick to beat",name:"Longer Than Five?",summary:"Hold up your 5-stick. Is the stick on the board longer or shorter?",grows:"This grows out of Number Stairs and the 5-Stick, where every stick on the table was held against a 5-stick and sorted as longer than or shorter than it.",steps:["Hold up your own 5-stick and look at the stick beside the 5-stick on the board.","Show longer or shorter, and how many cubes the stick has, with cubes, fingers or a number card.","Tap Reveal and count the stick together, cube by cube."],materials:"Linking cubes, a 5-stick, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:4,id:"same-as-the-gray-stick",iso:"2026-11-16",date:"Mon 16 Nov 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 5–7",preferred:5,focus:"together, the same length",name:"Same as the Gray Stick",summary:"Show how many cubes make the stick the same length as the gray stick.",grows:"This grows out of the riddle of the 5-stick, where two short sticks laid end to end under the 5-stick were together the same length as it.",steps:["Look at the gray stick and the coloured part under it.","Show how many more cubes the other part needs, with cubes, fingers, a number card or by pointing.","Tap Reveal, watch the missing part slide in, and count its cubes together."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:4,id:"tip-the-balance",iso:"2026-11-18",date:"Wed 18 Nov 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 8–9",preferred:3,focus:"the heavier side goes down",name:"Tip the Balance",summary:"Show which side will go down, then reveal the balance tipping.",grows:"This grows out of the ruler balance, where the room guessed first and then watched the heavier side go down, even when it was the smaller thing.",steps:["Look at the two things on the balance.","Point, tip a hand or say which side will go down, or say they will stay level.","Tap Reveal and watch the balance tip, or stay level."],materials:"A ruler balance, two things from the tray, hands to tip, or a device",brainGame:"Measure Masters"},{unit:4,id:"as-heavy-as",iso:"2026-11-20",date:"Fri 20 Nov 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 10–12",preferred:10,focus:"count the units until it balances, then switch the units",name:"As Heavy As",summary:"Count how many units make the balance level, then switch the units and count again.",grows:"This grows out of the ruler balance, where chips and then cubes were added one at a time beside a pencil and a marker until the ruler lay level.",steps:["Look at the thing on the balance and the small picture that says what to add.","Show how many cubes or chips will make it level, with fingers, cubes, a number card or by pointing.","Tap Reveal, watch them drop in one at a time, and count together until it is level."],materials:"A ruler balance, linking cubes, bingo chips, fingers, number cards 0 to 20, or a device",brainGame:"Measure Masters"},{unit:4,id:"pour-and-count",iso:"2026-12-01",date:"Tue 1 Dec 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 13–14",preferred:10,focus:"pour it anywhere, the amount stays the same",name:"Pour and Count",summary:"Count the cubes, watch them pour into a new container, and show how many are there now.",grows:"This grows out of the drawer of cubes poured into the tall tumbler, where it only went partway up but filled the drawer again when poured back.",steps:["Count the cubes in the first container together.","Watch them pour into the new container, then show how many are there now, with cubes, fingers, a number card or by pointing.","Tap Reveal and count them in the new container together."],materials:"Loose linking cubes, two containers, fingers, number cards 0 to 20, or a device",brainGame:"Measure Masters"},{unit:4,id:"longer-heavier-holds-more",iso:"2026-12-03",date:"Thu 3 Dec 2026",source:"Bluebonnet Kindergarten Math Module 3, Mid-Module Assessment (Topics A–D)",preferred:10,focus:"say what we compare, then compare",name:"Longer, Heavier, Holds More",summary:"See what this round compares, then show the longer, the heavier, or the one that holds more.",grows:"This grows out of the review, where the room lined up pencils, compared cube sticks, held a book and a ball, and poured a drawer into the tumbler.",steps:["Look at the small picture that says what we compare: a ruler, a hand-scale or a cup.","Point to the longer, the heavier, or the one that holds more, or show that they are the same.","Tap Reveal and watch the two slide together, the balance tip, or the cubes pour."],materials:"Linking cubes, two things from the tray, a container, fingers, number cards 0 to 20, or a device",brainGame:"Measure Masters"},{unit:4,id:"enough-for-everyone",iso:"2026-12-07",date:"Mon 7 Dec 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 15–16",preferred:5,focus:"one for each, then look",name:"Enough for Everyone?",summary:"Match one to one and show how many more we need.",grows:"This grows out of Set the Table, where one board, one marker, one tub and one pouch went to each person and the room found enough, not enough or too many.",steps:["Look at the friends and the things.","Show how many more things we need so everyone has one.","Tap Reveal, watch the lines match, and count the ones left without."],materials:"Linking cubes, Play-Doh tubs, fingers, number cards 0 to 10, or a device",brainGame:"Croc Snack Cannon"},{unit:4,id:"line-them-up",iso:"2026-12-09",date:"Wed 9 Dec 2026",source:"Bluebonnet Kindergarten Math Module 3, Lessons 17–18",preferred:5,focus:"match one to one, then look for the leftovers",name:"Line Them Up",summary:"Match the two rows and show how many are left over.",grows:"This grows out of Fewer Than, where the chips and the cubes were matched one to one, one cube put back at a time, until fewer became the same.",steps:["Look at the two rows.","Show how many are left over when you match them one to one.","Tap Reveal, watch the pairs join, and point to the row with fewer."],materials:"Linking cubes, bingo chips, fingers, number cards 0 to 10, or a device",brainGame:"Croc Snack Cannon"},{unit:4,id:"taller-tower",iso:"2026-12-11",date:"Fri 11 Dec 2026",source:"Teacher-created: Flying Machine groups",preferred:5,focus:"line them up, then compare",name:"Taller Tower",summary:"Count each tower, then show how many more the taller one has.",grows:"This grows out of sorting the class’s Flying Machine versions into push, pull and wind, building a cube tower for each group, and comparing the towers.",steps:["Look at the two towers.","Show how many more cubes the taller tower has.","Tap Reveal, watch the towers line up, and count the extra."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:5,id:"longer-stick-more-cubes",iso:"2027-01-07",date:"Thu 7 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lessons 19–20",preferred:5,focus:"longer means more",name:"Longer Stick, More Cubes",summary:"Two sticks start together — show how many cubes are in the longer one.",grows:"This grows out of Roll, Build, Compare, where partners rolled a die, built a stick for each roll, compared their lengths and then compared the cubes as sets.",steps:["Look at the two sticks, lined up at one end.","Show how many cubes are in the longer stick, with cubes, fingers or a number card.","Tap Reveal and watch both sticks count up and the extra cubes light."],materials:"Linking cubes, a die, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:5,id:"same-then-one-more",iso:"2027-01-11",date:"Mon 11 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lessons 21–22",preferred:5,focus:"match one to one, then one more",name:"Same, Then One More",summary:"Make a set the same as this one — then a set with one more.",grows:"This grows out of Match My Set and One More Than My Set, where partners built a chip set to match a cube set and then a chip set with one more.",steps:["Look at the set and show how many make the same set.","Tap Reveal and watch each thing get a partner.","Now show one more, then tap Reveal and watch the extra one light up."],materials:"Linking cubes and bingo chips, a die, fingers, number cards 0 to 10, or a device",brainGame:"Labyrinth Stairs"},{unit:5,id:"one-less-worm",iso:"2027-01-13",date:"Wed 13 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lessons 23–24",preferred:5,focus:"one fewer, then check",name:"One Less Worm",summary:"Every bird but one gets a worm — show how many worms.",grows:"This grows out of The Birds Are Back and One Fewer Than My Set, where students drew one fewer worm than birds and built chip sets with one fewer.",steps:["Look at the birds in the row.","Show how many worms make one fewer, with cubes, fingers or a number card.","Tap Reveal and watch each worm go to a bird, and one bird wait without."],materials:"Linking cubes and bingo chips, a die, fingers, number cards 0 to 10, or a device",brainGame:"Labyrinth Stairs"},{unit:5,id:"pair-them-up",iso:"2027-01-15",date:"Fri 15 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lessons 25–26",preferred:5,focus:"match, then say more and less",name:"Pair Them Up",summary:"Two messy sets — line them up, pair them up, and find the leftovers.",grows:"This grows out of Line Them Up and Which Is Less?, where the room redrew scattered shapes in rows and columns and matched them with lines to see which had more.",steps:["Look at the two scattered sets.","Show how many are in the set with more, with cubes, fingers or a number card.","Tap Reveal and watch the sets line up, pair up, and light the leftovers."],materials:"Linking cubes and bingo chips, fingers, number cards 0 to 10, or a device",brainGame:"Croc Snack Cannon"},{unit:5,id:"count-the-taps",iso:"2027-01-20",date:"Wed 20 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lessons 27–28",preferred:5,focus:"picture it, then compare",name:"Count the Taps",summary:"Listen to two sets of taps — which set had more?",grows:"This grows out of Listen and Compare, where the room closed their eyes, counted two sets of taps on the table, and said which number was greater.",steps:["Listen to the first set of taps, then the second.","Show the number in the set that had more, with cubes, fingers or a number card.","Tap Reveal and watch the dots line up and the extra ones light."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Croc Snack Cannon"},{unit:5,id:"more-less-same",iso:"2027-01-22",date:"Fri 22 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, End-of-Module Assessment Task (Topics E–G)",preferred:10,focus:"the whole topic, mixed",name:"More, Less, Same",summary:"Every round asks one of the month’s questions — more, less, same, one more, one less.",grows:"This grows out of the End-of-Module Assessment Task, where students had just answered the module’s comparing questions box by box on paper.",steps:["Look at the two sets or numbers and the question sign.","Show your answer with cubes, fingers or a number card.","Tap Reveal and watch the sets line up and the answer light."],materials:"Linking cubes and bingo chips, fingers, number cards 0 to 10, or a device",brainGame:"Croc Snack Cannon"},{unit:5,id:"two-paths-home",iso:"2027-01-26",date:"Tue 26 Jan 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 1–2",preferred:5,focus:"two parts make the whole",name:"Two Paths Home",summary:"The stick breaks in two — one part goes home, show the part that is hiding.",grows:"This grows out of the Party Game and Leaving the Party, where students walked the two paths of a floor number bond and broke a 5-stick into two parts, one down each path.",steps:["Look at the whole stick at the top of the number bond, and watch one part slide down its path.","Show the hidden part with cubes, fingers or a number card.","Tap Reveal, watch the other part slide down, then watch both go back up into the whole."],materials:"A 5-stick of linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:5,id:"numbers-for-pictures",iso:"2027-01-28",date:"Thu 28 Jan 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 3–4",preferred:5,focus:"the whole goes where the paths meet",name:"Numbers for Pictures",summary:"Count the squares in one circle and show the number that can take their place.",grows:"This grows out of Squirrels in the Park and Five Apples, where the room drew squares in a number bond and then erased them and wrote the numerals instead, whole and parts.",steps:["Look at the squares in the circle that is lit.","Show how many with cubes, fingers or a number card.","Tap Reveal and watch the squares turn into the number, then do the next circle."],materials:"Linking cubes, a whiteboard number bond, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:5,id:"snap-find-the-other-part",iso:"2027-02-01",date:"Mon 1 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 5–6",preferred:5,focus:"find the hidden part",name:"Snap! Find the Other Part",summary:"The stick snaps — one part hides. Show the part that is hiding.",grows:"This grows out of Snap and A Bond With No Story, where students broke a 5-stick behind their backs, showed one part, and found the other, then told stories for a bond.",steps:["Look at the whole stick, then watch it snap and one part hide.","Show the hidden part with cubes, fingers or a number card.","Tap Reveal to lift the screen and see the number bond."],materials:"A 5-stick of linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:5,id:"every-way-to-seven",iso:"2027-02-03",date:"Wed 3 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 7–8",preferred:10,focus:"every way to break 7",name:"Every Way to Seven",summary:"The same 7 breaks a new way every round — show one part and grow the list.",grows:"This grows out of The Squirrel’s Nuts and Sets of Shapes, where the room broke a 6-stick every way and sorted 7 pattern blocks into two sets again and again.",steps:["Look at the whole number and watch the stick split a new way.","Show one of the parts with cubes, fingers or a number card.","Tap Reveal to fill the bond and add it to the list of ways."],materials:"A 7-stick of linking cubes, pattern blocks, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:5,id:"which-row-has-more",iso:"2027-02-05",date:"Fri 5 Feb 2027",source:"Teacher-created on Kindergarten Math Modules 3 and 4",preferred:10,focus:"read the graph",name:"Which Row Has More?",summary:"Look at the picture graph — point to the row with more, and show how many more.",grows:"This grows out of our medallion towers, where every Hero Medallion became a cube in a red, blue or yellow tower and the towers became rows on our picture graph.",steps:["Look at the rows of coloured squares on the graph.","Point to the colour with more, and show how many more with cubes, fingers or a number card.","Tap Reveal and count the extra squares together."],materials:"Linking cubes in three colours, fingers, number cards 0 to 10, or a device",brainGame:"Picture Graph Parade"},{unit:6,id:"whats-behind-my-back",iso:"2027-02-09",date:"Tue 9 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 9–10",preferred:10,focus:"the parts make the whole",name:"What's Behind My Back?",summary:"You see the whole and one part of the stick. Show the part behind its back.",grows:"This grows out of Snap! and One Cube at a Time, where the room broke a 6-, 7- and 8-stick behind their backs, showed one part and said the other, then moved one cube at a time to find every pair.",steps:["Read the whole and count the part of the stick you can see.","Show the hidden part with cubes, fingers or a number card.","Tap Reveal to bring the hidden part out and fill the number bond."],materials:"An 8-cube stick, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:6,id:"full-five-then-more",iso:"2027-02-11",date:"Thu 11 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 11–12",preferred:10,focus:"five and some more",name:"Full Five, Then More",summary:"The top row is full. Count on to find how many in all.",grows:"This grows out of Five and Some More, where the room filled the top row of five boxes first, put the extra cubes in the row below and counted on from 5.",steps:['Look at the full top row and say "five."',"Count on along the bottom row, then show how many in all with cubes, fingers or a number card.","Tap Reveal to count on from 5 together and see the number bond."],materials:"Eight linking cubes, two rows of five boxes drawn on a whiteboard, fingers, number cards 0 to 10, or a device",brainGame:"Quick Look Lighthouse"},{unit:6,id:"ducks-on-the-shore",iso:"2027-02-16",date:"Tue 16 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 13–15",preferred:10,focus:"two parts, one number sentence",name:"Ducks on the Shore",summary:"The ducks land on the shore and in the water. Show both parts and the whole.",grows:"This grows out of the ducks poured over the Long Wooden Block, where the room counted the shore and the water and wrote the number sentence both ways.",steps:["Count the ducks on the shore and the ducks in the water.","Show the two parts and the whole with cubes, fingers or number cards.","Tap Reveal to count each side and see the number sentence written two ways."],materials:"Eight linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:6,id:"mystery-box",iso:"2027-02-18",date:"Thu 18 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 16–18",preferred:10,focus:"box the unknown",name:"Mystery Box",summary:"Some are there, and some more come. What goes in the mystery box?",grows:"This grows out of Kittens in the Yard, where the room pictured the story, drew it, wrote 5 + 2 = □ and found what goes in the box.",steps:["Watch the first group, then the ones that come to join them.","Show what goes in the mystery box with cubes, fingers or a number card.","Tap Reveal to count them all and open the box."],materials:"Eight linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:6,id:"how-many-are-left",iso:"2027-02-22",date:"Mon 22 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 19–21",preferred:5,focus:"cross out, then count what is left",name:"How Many Are Left?",summary:"Some go away. Show how many are left.",grows:"This grows out of Five Sparkly Fireworks, the cubes taken off the table and the frogs that swam, where the room crossed out the ones that went away and counted the rest.",steps:["Count the group on the board.","Watch some go away, then show how many are left with cubes, fingers or a number card.","Tap Reveal and count what is left together."],materials:"Five linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:6,id:"break-the-stick",iso:"2027-02-24",date:"Wed 24 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 22–24",preferred:10,focus:"the whole is two parts",name:"Break the Stick",summary:"Part of the stick breaks off. How many are left?",grows:"This grows out of Snap and Break It Off, where the room broke, hid and crossed off part of a 6-, 7- and 8-stick and wrote the number bond each time.",steps:["Look at the whole stick and say how many cubes.","Watch part of it break off, then show how many are left with cubes, fingers or a number card.","Tap Reveal to put the stick back together and see the number bond."],materials:"A 6-, 7- or 8-cube stick, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:6,id:"find-the-hidden-part",iso:"2027-02-26",date:"Fri 26 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Mid-Module Assessment Task (Topics A–D)",preferred:10,focus:"find the missing part",name:"Find the Hidden Part",summary:"You see the whole and one part. Show the hidden part.",grows:"This grows out of the week's number bonds, the sticks broken and hidden on Monday and Wednesday, and the bonds on the Mid-Module task.",steps:["Read the whole in the circle and count the part you can see.","Show the hidden part with cubes, fingers or a number card.","Tap Reveal to lift the card and check the number bond."],materials:"Eight linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:6,id:"nine-bears-two-places",iso:"2027-03-02",date:"Tue 2 Mar 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 25–26",preferred:10,focus:"nine is many pairs",name:"Nine Bears, Two Places",summary:"Some bears are outside. How many are in the cave?",grows:"This grows out of Nine Bears and Lee's Blocks, where the room split nine bears between the forest and the cave and broke a 9-stick one cube at a time.",steps:["Count the bears outside the cave.","Show how many are hiding inside with cubes, fingers or a number card.","Tap Reveal to open the cave and see the number bond."],materials:"Nine linking cubes in two colours, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:6,id:"count-the-vote",iso:"2027-03-04",date:"Thu 4 Mar 2027",source:"Teacher-created (Module 4 strands; Lesson 20 Application Problem graph)",preferred:10,focus:"more, fewer, how many in all",name:"Count the Vote",summary:"Look at the graph. Which side has more? How many more?",grows:"This grows out of Our Tally and Make It a Picture Graph, where the room drew one picture for each vote and built the vote as two cube towers.",steps:["Look at the two columns and point to the taller one.","Show how many more, or how many in all, with cubes, fingers or a number card.","Tap Reveal to match the pictures up and count together."],materials:"Ten linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Picture Graph Parade"},{unit:6,id:"pieces-on-the-wall",iso:"2027-03-09",date:"Tue 9 Mar 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 13–26 (review)",preferred:10,focus:"add to and take from, to 9",name:"Pieces on the Wall",summary:"Some pieces go up or fall down. How many are on the wall now?",grows:"This grows out of Pieces Go Up and Pieces Fall Down, where the room built the exhibition wall's medallions and flags as cube trains and wrote the number sentence for each story.",steps:["Count the pieces on the wall.","Watch pieces go up or fall down, then show how many are on the wall now with cubes, fingers or a number card.","Tap Reveal to count the wall and see the number sentence."],materials:"Nine linking cubes in two colours, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:6,id:"tally-the-visitors",iso:"2027-03-11",date:"Thu 11 Mar 2027",source:"Teacher-created (Module 4 strands; Lesson 26, five and some more)",preferred:10,focus:"tally marks in fives",name:"Tally the Visitors",summary:"Visitors walk by. One mark each. How many came?",grows:"This grows out of One Mark for One Visitor and Our Tally Sheet, where the room made one tally mark for each visitor, drew the fifth across, and counted the bundle first, then on.",steps:["Watch the visitors walk past and the tally marks appear.","Show how many visitors came with cubes, fingers or a number card.","Tap Reveal to count the bundle of five and count on."],materials:"Ten linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Quick Look Lighthouse"},{unit:7,id:"ants-leave-the-picnic",iso:"2027-03-23",date:"Tue 23 Mar 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 27–28",preferred:10,focus:"ten keeps its parts",name:"Ants Leave the Picnic",summary:"Some ants crawl off the blanket. How many are still on it?",grows:"This grows out of Ants at the Picnic, where ten cube ants left a whiteboard blanket one at a time and the room drew each new bond.",steps:["Look at the ants on the blanket and the ones crawling away.","Show how many are still on the blanket with cubes, fingers or a number card.","Tap Reveal to see the number bond, with 10 as the whole."],materials:"A linking-cube 10-stick, a whiteboard, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:7,id:"parts-first-whole-first",iso:"2027-03-25",date:"Thu 25 Mar 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 29–30",preferred:10,focus:"the whole can go first",name:"Parts First, Whole First",summary:"Two kinds of dots. Show the parts, then the whole.",grows:"This grows out of Nine the 5-Group Way, where one drawing gave 9 = 5 + 4 and 5 + 4 = 9.",steps:["Look at the 5-group drawing and its two kinds of dots.","Show the two parts and the whole with cubes, fingers or number cards.","Tap Reveal to see the number sentence written both ways round."],materials:"Linking cubes in two colours, a whiteboard, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:7,id:"bears-in-the-forest",iso:"2027-03-31",date:"Wed 31 Mar 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 31–32",preferred:10,focus:"part plus part makes the whole",name:"Bears in the Forest",summary:"Some bears, then more bears. How many in all?",grows:"This grows out of Six Bears and Three More, where cube bears were joined by more and the room counted on to the total.",steps:["Look at the bears in the forest and the ones arriving.","Show how many bears in all with cubes, fingers or a number card.","Tap Reveal to count on together and see the number sentence."],materials:"Linking cubes, a whiteboard, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:7,id:"sleepy-bears",iso:"2027-04-02",date:"Fri 2 Apr 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 33–34",preferred:10,focus:"whole take away part",name:"Sleepy Bears",summary:"Some bears go to sleep in the cave. How many are still awake?",grows:"This grows out of Break It, Cross It Out, Hide It, where bears went under a paper cave and the room counted the ones still awake.",steps:["Look at all the bears, then watch some walk into the cave.","Show how many are still awake with cubes, fingers or a number card.","Tap Reveal to lift the cave and see the subtraction sentence."],materials:"Linking cubes, a sheet of paper folded into a cave, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:7,id:"ripe-peaches",iso:"2027-04-06",date:"Tue 6 Apr 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 35–36",preferred:10,focus:"cross off the part that goes away",name:"Ripe Peaches",summary:"Some peaches are still green. How many are ready?",grows:"This grows out of Melanie’s Peaches and Chris’s Cars, where the unripe peaches were circled and crossed off a 5-group drawing.",steps:["Look at the peaches and find the green ones.","Show how many are ripe with cubes, fingers or a number card.","Tap Reveal to cross off the green ones and see the subtraction sentence."],materials:"Linking cubes, a whiteboard, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:7,id:"frogs-hop-back",iso:"2027-04-08",date:"Thu 8 Apr 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 37–38",preferred:10,focus:"adding and taking away the same number undo each other",name:"Frogs Hop Back",summary:"Frogs hop on, then the same frogs hop off. How many now?",grows:"This grows out of Pigeons and Pinecones, where 5 pigeons came and the same 5 flew away, and the room landed back where it started.",steps:["Look at the frogs on the log.","Show how many after more hop on, then after the same frogs hop off, with cubes, fingers or a number card.","Tap Reveal to see both number sentences."],materials:"Linking cubes, a number path 1 to 10, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:7,id:"ten-needs-a-partner",iso:"2027-04-12",date:"Mon 12 Apr 2027",source:"Bluebonnet Kindergarten Math Module 4, Lessons 39–40",preferred:10,focus:"how many more make ten",name:"Ten Needs a Partner",summary:"Look at the frame. Show how many more make 10.",grows:"This grows out of The Cat Needs 10 and Break the 10-Stick, where the room finished 5-group drawings to 10 and broke a 10-stick into two parts.",steps:["Look at the ten-frame and count the dots.","Show how many more make 10 with cubes, fingers or a number card.","Tap Reveal, watch the empty boxes fill, and say the number sentence together."],materials:"A linking-cube 10-stick, ten-frame cards, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:7,id:"ten-and-some-more",iso:"2027-04-14",date:"Wed 14 Apr 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 1–2",preferred:20,focus:"ten ones and some more ones",name:"Ten and Some More",summary:"The ten is full. How many more ones?",grows:"This grows out of Ten Ones and Some More, where handfuls filled a ten-frame and the extras waited beside it.",steps:["Look at the full ten-frame and the loose ones beside it.","Show how many loose ones with cubes, fingers or a number card, and say “10 ones and ___ ones.”","Tap Reveal and count the loose ones together, then say the teen number."],materials:"Linking cubes, a ten-frame drawn on a whiteboard, fingers, number cards 0 to 20, or a device",brainGame:"Quick Look Lighthouse"},{unit:7,id:"say-it-the-ten-way",iso:"2027-04-16",date:"Fri 16 Apr 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 3–5",preferred:20,focus:"ten and some ones, the Say Ten way",name:"Say It the Ten Way",summary:"Count the ten, then the ones. Say it the ten way.",grows:"This grows out of The Say Ten Way and Build It the Say Ten Way, where ten was held still and ones were added one at a time and named.",steps:["Look at the ten-train and the loose cubes.","Say or show the Say Ten name — ten 4 — with cubes, fingers, a number card or a device.","Tap Reveal to ring the ten and count the ones together."],materials:"A linking-cube train of 10, loose linking cubes, fingers, number cards 0 to 20, or a device",brainGame:"Quick Look Lighthouse"},{unit:7,id:"missing-part",iso:"2027-04-21",date:"Wed 21 Apr 2027",source:"Bluebonnet Kindergarten Math Module 4, End-of-Module review (Topics E–H)",preferred:10,focus:"the parts make the whole",name:"Missing Part",summary:"Look at the whole and one part. Show the missing part.",grows:"This grows out of Ten in Two Parts, where the room broke 10-sticks and 9-sticks into two parts and drew them as number bonds.",steps:["Look at the whole and the part you can see.","Show the missing part with cubes, fingers or a number card.","Tap Reveal to fill the bond and say the number sentence together."],materials:"A linking-cube 10-stick, fingers, number cards 0 to 10, or a device",brainGame:"Penguin Iceberg Rescue"},{unit:7,id:"which-week-has-more",iso:"2027-04-23",date:"Fri 23 Apr 2027",source:"Teacher-created",preferred:20,focus:"more, fewer or the same",name:"Which Week Has More?",summary:"Look at the two towers. Which has more, and how many more?",grows:"This grows out of Cube Towers and Compare, where the class built one tower for each week’s patch count and counted the extra cubes on the taller one.",steps:["Look at the two towers standing side by side.","Point to the taller one and show how many more cubes it has, or show that they are the same.","Tap Reveal and count the extra cubes together."],materials:"Linking cubes in two colours, fingers, number cards 0 to 20, or a device",brainGame:"Picture Graph Parade"},{unit:8,id:"slide-over-the-zero",iso:"2027-04-27",date:"Tue 27 Apr 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 6–7",preferred:10,focus:"ten hides its zero",name:"Slide Over the Zero",summary:"Look at the ten and the ones. Show the number. Watch the ones card slide over the zero.",grows:"This grows out of The Hiding Zero, where the room pushed a paper 8 over the zero of a paper 10 and read ten 8, eighteen.",steps:["Look at the ten-stick and the ones.","Show the number with cubes, fingers or a number card.","Tap Reveal to slide the ones card over the zero and count the ones together."],materials:"Linking cubes in two colours, fingers, number cards 0 to 20, or a device",brainGame:"Quick Look Lighthouse"},{unit:8,id:"fill-one-frame-first",iso:"2027-04-29",date:"Thu 29 Apr 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 8–9",preferred:20,focus:"fill ten first",name:"Fill One Frame First",summary:"Look at the pile. How many? Watch ten fill the first frame.",grows:"This grows out of Fill Ten First, where the room drew teen numbers in two ten-frames and filled one frame before starting the next.",steps:["Look at the pile of dots.","Show how many with cubes, fingers or a number card.","Tap Reveal to fill the first frame, then the next, and say the number the Say Ten way."],materials:"Linking cubes, fingers, number cards 0 to 20, or a device",brainGame:"Quick Look Lighthouse"},{unit:8,id:"one-more-one-less",iso:"2027-05-03",date:"Mon 3 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 10–12",preferred:20,focus:"one more, one less",name:"One More, One Less",summary:"Watch one cube land on the tower or lift off. Show the new number.",grows:"This grows out of One More and One Less, where the room put one cube on a tower or took one off and said the new number.",steps:["Look at the tower and its number.","Watch one cube land or lift off. Show the new number with cubes, fingers or a number card.","Tap Reveal to count the tower together."],materials:"A linking-cube tower, fingers, number cards 0 to 20, or a device",brainGame:"Labyrinth Stairs"},{unit:8,id:"same-count-new-shape",iso:"2027-05-05",date:"Wed 5 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 13–14",preferred:20,focus:"same count, new shape",name:"Same Count, New Shape",summary:"Count the dots. Watch them change shape. How many now?",grows:"This grows out of One Train, Many Shapes and Around the Plate, where the room broke a cube train into rows and moved cubes from a circle into a ten-frame.",steps:["Count the dots in the line and show how many.","Watch the dots move into rows or a ring. Show how many now.","Tap Reveal to count them together."],materials:"Linking cubes, fingers, number cards 0 to 20, or a device",brainGame:"Apple Count Orchard"},{unit:8,id:"more-fewer-equal",iso:"2027-05-07",date:"Fri 7 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 15–16",preferred:20,focus:"line them up to compare",name:"More, Fewer, Equal",summary:"Look at the two groups. Which has more? Or are they equal?",grows:"This grows out of Are They Equal?, where the room laid two cube lines side by side to see which had more.",steps:["Look at the two groups of dots.","Point to the group with more, or show that they are equal.","Tap Reveal to pair the dots and see."],materials:"Linking cubes in two colours, fingers, or a device",brainGame:"Croc Snack Cannon"},{unit:8,id:"tens-up-the-stairs",iso:"2027-05-11",date:"Tue 11 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 17–18",preferred:10,focus:"count by tens",name:"Tens Up the Stairs",summary:"Count the ten-frames by tens. How many in all?",grows:"This grows out of Count the Sticks by Tens and Show Me Tens, where the room slid cube sticks of ten across the table counting 10, 20, 30 and back down.",steps:["Look at the ten-frames on the stairs.","Count them by tens and show how many in all with cube sticks, fingers or a number card.","Tap Reveal and count the stairs by tens together."],materials:"Linking-cube sticks of ten, fingers, number cards 0 to 100, or a device",brainGame:"Quick Look Lighthouse"},{unit:8,id:"over-the-ten",iso:"2027-05-13",date:"Thu 13 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 19–20",preferred:10,focus:"nine, then a new ten",name:"Over the Ten",summary:"One more, one less: what is the number now?",grows:"This grows out of Count Across the Ten and Over the Ten, where one more cube went past the end of a stick into a new ten and one cube came back.",steps:["Look at the tens and ones on the board.","Watch one cube come on or go off, and show the new number with cubes, fingers or a number card.","Tap Reveal and see if a new ten lights up."],materials:"Linking-cube sticks of ten, loose cubes, fingers, number cards 0 to 100, or a device",brainGame:"Quick Look Lighthouse"},{unit:8,id:"earn-it-or-gift-it",iso:"2027-05-17",date:"Mon 17 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 25–27",preferred:10,focus:"earned plus given",name:"Earn It or Gift It?",summary:"Pennies you earned and pennies you were given: how many in all?",grows:"This grows out of Shana’s Pennies and Income or Gift?, where the room joined pennies earned at a job and pennies given as a gift in one number bond.",steps:["Look at the pennies by the job and the pennies in the gift box.","Show how many pennies in all with cubes, fingers or a number card.","Tap Reveal and see the two parts join into one bond."],materials:"Linking cubes as pennies, fingers, number cards 0 to 20, or a device",brainGame:"Coin Fishing"},{unit:8,id:"fits-the-budget",iso:"2027-05-19",date:"Wed 19 May 2027",source:"Teacher-created (budget from the class plan; Module 5 Topic F and Module 4 number bonds)",preferred:10,focus:"spend some, some left",name:"Fits the Budget",summary:"Pay the price. How many are left?",grows:"This grows out of Pay for It, where cubes left the class cup to pay for each item the plan needed and the room counted what was left.",steps:["Look at the cubes in the cup and the price tag.","Show how many cubes will be left after paying, with cubes, fingers or a number card.","Tap Reveal and watch the price leave the cup."],materials:"Ten linking cubes in a cup, fingers, number cards 0 to 20, or a device",brainGame:"Coin Fishing"},{unit:8,id:"taller-bean",iso:"2027-05-21",date:"Fri 21 May 2027",source:"Teacher-created (our year in numbers: the class's bean plants)",preferred:10,focus:"how many more",name:"Taller Bean",summary:"Which bean is taller, and by how many cubes?",grows:"This grows out of Our Plants and Our Plant Graph, where every bean plant became a cube tower lined up on the table edge and a row on the class graph.",steps:["Look at the two bean plants and their cube sticks.","Point to the taller one and show how many cubes more with cubes, fingers or a number card.","Tap Reveal and count the extra cubes together."],materials:"Linking-cube sticks, fingers, number cards 0 to 20, or a device",brainGame:"Croc Snack Cannon"},{unit:8,id:"tally-at-the-door",iso:"2027-05-25",date:"Tue 25 May 2027",source:"Review of Bluebonnet Kindergarten Math Module 5 (Lessons 7, 13–14, 17 and 20) and teacher-created tally marks for School Exhibition #4",preferred:20,focus:"bundles of five, then ten and some ones",name:"Tally at the Door",summary:"Visitors come in. How many came?",grows:"This grows out of Tally Marks, where one line went up for each cube dropped in the cup and the fifth line went across to make a bundle of five.",steps:["Watch the visitors come through the door and the tally grow.","Show how many visitors came with cubes, fingers or a number card.","Tap Reveal and count the bundles by fives, then the ones."],materials:"Linking cubes in a cup, fingers, number cards 0 to 20, or a device",brainGame:"Quick Look Lighthouse"},{unit:4,id:"which-plane-is-heavier",iso:"2026-12-15",date:"Tue 15 Dec 2026",source:"Teacher-created Flight Lab (Bluebonnet Kindergarten Math Module 3, Topic C)",preferred:5,focus:"more cargo, the heavier side goes down",name:"Which Plane Is Heavier?",summary:"Load the two planes, then show which side of the balance goes down.",grows:"This grows out of Bigger or Heavier?, where two cubes taped to a small plane’s nose made the balance go down beside a bigger plane.",steps:["Look at the two planes and their cubes.","Show which side will go down, or show “the same.”","Tap Reveal, watch the balance tip, and count the cubes."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:4,id:"our-flight-chart",iso:"2026-12-17",date:"Thu 17 Dec 2026",source:"Teacher-created: our Flight Lab results (Bluebonnet Kindergarten Math Module 3, Topic E)",preferred:5,focus:"match the rows, then say more, fewer, or the same",name:"Plane Rows",summary:"Match the two rows of planes and show which has more, fewer, or the same.",grows:"This grows out of Our Flight Chart, where each student put one cube for their plane in the “past the rug” or the “on the rug” row and the room lined the rows up one to one.",steps:["Look at the two rows of planes.","Point to the row with more, or show “the same.”","Tap Reveal, watch the planes match, and count the extras."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:4,id:"holds-more",iso:"2026-11-30",date:"Mon 30 Nov 2026",source:"Bluebonnet Kindergarten Math Module 3, Lesson 13",preferred:10,focus:"which holds more: guess, then fill and see",name:"Holds More",summary:"Two containers. Which one holds more cubes? Guess, then fill them both and see.",grows:"This grows out of pouring cubes from one container into another to find which holds more, which holds less, or that they hold the same.",steps:["Look at the two containers. A tall one does not always hold more.","Point to the one you think holds more, or show it with a card.","Tap Reveal, watch both fill, and count the cubes in each."],materials:"Loose linking cubes, two containers from the teacher set, fingers, number cards 0 to 10, or a device",brainGame:"Measure Masters"},{unit:4,id:"which-has-more",iso:"2026-12-14",date:"Mon 14 Dec 2026",source:"Bluebonnet Kindergarten Math Module 3, Lesson 20",preferred:5,focus:"the taller column has more",name:"Which Has More?",summary:"Marchers fill two columns of the graph. Which column has more?",grows:"This grows out of lining two sets up in a graph and saying which has more, which has fewer, or that they have the same number.",steps:["Watch each marcher drop a picture into its column.","When the graph is full, point to the column with more, or hold up its picture.","Tap Reveal to match the columns one to one and see the extras."],materials:"Linking cubes in two colours, fingers, or a device",brainGame:"Picture Graph Parade"},{unit:5,id:"the-most-the-fewest",iso:"2027-01-07",date:"Thu 7 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lesson 24",preferred:10,focus:"read a picture graph: the most and the fewest",name:"The Most, the Fewest",summary:"Three kinds of marchers fill a picture graph. Which column has the most? Which has the fewest?",grows:"This grows out of making a picture graph from the room’s own count and saying what the graph shows.",steps:["Watch each marcher drop a picture into its column.","Point to the column with the most, then the column with the fewest.","Tap Reveal to count each column together."],materials:"Linking cubes in three colours, fingers, number cards 0 to 10, or a device",brainGame:"Picture Graph Parade"},{unit:5,id:"feed-the-croc-with-more",iso:"2027-01-08",date:"Fri 8 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lesson 25",preferred:5,focus:"match and count: which is more",name:"Feed the Croc with More",summary:"Each croc wears a set. Match them in your head and feed the croc with more.",grows:"This grows out of matching two sets one to one and counting to find which is more.",steps:["Look at the two sets the crocs wear.","Point to the croc with more, or show it with cubes or a card.","Tap Reveal to match the sets one to one and see the extras."],materials:"Linking cubes in two colours, fingers, number cards 0 to 5, or a device",brainGame:"Croc Snack Cannon"},{unit:5,id:"feed-the-croc-with-fewer",iso:"2027-01-12",date:"Tue 12 Jan 2027",source:"Bluebonnet Kindergarten Math Module 3, Lesson 27",preferred:5,focus:"fewer or more: choose how to compare",name:"Feed the Croc with Fewer",summary:"Some rounds ask for fewer and some ask for more. Listen, then feed the right croc.",grows:"This grows out of choosing a way to compare two sets: matching them, lining them up, or counting.",steps:["Listen: does this round ask for fewer or for more?","Compare the two sets your own way and point to the croc.","Tap Reveal to match the sets and see which one runs out first."],materials:"Linking cubes in two colours, fingers, number cards 0 to 5, or a device",brainGame:"Croc Snack Cannon"},{unit:5,id:"the-big-sign",iso:"2027-02-04",date:"Thu 4 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 13",preferred:6,focus:"an addition story and its number sentence, to 6",name:"The Big Sign",summary:"Guests come on stage. Tell the story, then build its number sentence on the big sign.",grows:"This grows out of telling addition stories to 6 with drawings and writing the number sentence with nothing hidden.",steps:["Count who is on the stage, then count who comes on.","Show the number sentence with cubes, fingers or number cards: how many, plus how many, equals how many.","Tap Reveal to see the sentence on the big sign and read it together."],materials:"Six linking cubes in two colours, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:6,id:"a-garden-of-possibilities",iso:"2027-02-08",date:"Mon 8 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 14",preferred:10,focus:"an addition story and its number sentence",name:"A Garden of Possibilities",summary:"Move Man pulls up carrots of two colours. Count each colour, then build the number sentence.",grows:"This grows out of telling addition stories with drawings and writing the number sentence with nothing hidden.",steps:["Help Move Man pull up the carrots, then count each colour.","Show the two parts and how many in all with cubes, fingers or number cards.","Tap Reveal to see the number sentence and read it together."],materials:"Ten linking cubes in two colours, fingers, number cards 0 to 10, or a device",brainGame:"Story Stage"},{unit:6,id:"goodbye-guests",iso:"2027-02-16",date:"Tue 16 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 19",preferred:5,focus:"some go away: how many are left",name:"Goodbye, Guests",summary:"Some guests go home. How many are left on the stage?",grows:"This grows out of acting out take-away stories with objects and drawings to find how many are left.",steps:["Count the guests on the stage.","Watch some go home, then show how many are left with cubes, fingers or a number card.","Tap Reveal and count the guests who stayed."],materials:"Five linking cubes, fingers, number cards 0 to 5, or a device",brainGame:"Story Stage"},{unit:8,id:"earned-or-gift",iso:"2027-05-17",date:"Mon 17 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lessons 26–27",preferred:10,focus:"money you work for is earned",name:"Earned or Gift?",summary:"Clem catches something. Was it earned by working, or was it a gift?",grows:"This grows out of talking about jobs as a way to earn income, and about what people need and what they want.",steps:["Watch what Clem catches.","Show earned or gift: point, hold up a card, or say it.","Tap Reveal to see where it goes and why."],materials:"A coin pouch from the teacher set, two cards for earned and gift, or a device",brainGame:"Coin Fishing"},{unit:8,id:"bigger-number",iso:"2027-05-24",date:"Mon 24 May 2027",source:"Bluebonnet Kindergarten Math Module 5, Lesson 23",preferred:20,focus:"compare two teen numbers",name:"Bigger Number",summary:"The crocs wear numbers up to 20. Feed the greater number, or the number that is less.",grows:"This grows out of comparing teen numbers by looking at the extra ones after the ten.",steps:["Read the two numbers the crocs wear.","Point to the greater number, or to the number that is less when the round asks for it.","Tap Reveal to count up and see which number comes later."],materials:"Number cards 0 to 20, cube sticks of ten and loose cubes, fingers, or a device",brainGame:"Croc Snack Cannon"},{unit:5,id:"partners-of-five",iso:"2027-01-25",date:"Mon 25 Jan 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 5",preferred:5,focus:"two parts that make 5",name:"Partners of Five",summary:"Find two cards that make 5. Each pair you find turns into a number bond.",grows:"This grows out of showing numbers to 5 as two parts, in pictures and in number bonds.",steps:["Look at the cards. Some show dots and some show a numeral.","Open one card. Everyone shows the partner that makes 5, with fingers, cubes or a number card.","Open the partner and read the number bond it makes together."],materials:"Linking cubes, fingers, number cards 0 to 5, or a device",brainGame:"Partner Pairs"},{unit:5,id:"partners-of-seven",iso:"2027-02-02",date:"Tue 2 Feb 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 11",preferred:7,focus:"two parts that make 7",name:"Partners of Seven",summary:"Find two cards that make 7. Each pair you find turns into a number bond.",grows:"This grows out of breaking 6, 7 and 8 into two parts and writing each one as a number bond.",steps:["Look at the cards. Some show dots and some show a numeral.","Open one card. Everyone shows the partner that makes 7, with fingers, cubes or a number card.","Open the partner and read the number bond it makes together."],materials:"Linking cubes, fingers, number cards 0 to 7, or a device",brainGame:"Partner Pairs"},{unit:6,id:"partners-of-nine",iso:"2027-03-03",date:"Wed 3 Mar 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 26 (review)",preferred:9,focus:"two parts that make 9",name:"Partners of Nine",summary:"Find two cards that make 9. Each pair you find turns into a number bond.",grows:"This grows out of breaking 9 into two parts with fingers and cubes and writing the number bonds.",steps:["Look at the cards. Some show dots and some show a numeral.","Open one card. Everyone shows the partner that makes 9, with fingers, cubes or a number card.","Open the partner and read the number bond it makes together."],materials:"Linking cubes, fingers, number cards 0 to 9, or a device",brainGame:"Partner Pairs"},{unit:7,id:"partners-of-ten",iso:"2027-04-09",date:"Fri 9 Apr 2027",source:"Bluebonnet Kindergarten Math Module 4, Lesson 39",preferred:10,focus:"two parts that make 10",name:"Partners of Ten",summary:"Find two cards that make 10. Each pair you find turns into a number bond.",grows:"This grows out of finding the number that makes 10 with a drawing in rows of five.",steps:["Look at the cards. Some show dots and some show a numeral.","Open one card. Everyone shows the partner that makes 10, with fingers, cubes or a number card.","Open the partner and read the number bond it makes together."],materials:"Linking cubes, fingers, number cards 0 to 10, or a device",brainGame:"Partner Pairs"}];export{e as c};
